/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `zhigu_insert_custormform24detailscf` AFTER INSERT ON `ld_customform24detailscf` FOR EACH ROW BEGIN

set @customform24id=null;
set @projectid=null;
set @panduancailiao=null;

SELECT id into @customform24id from ld_customform24detail where lineitem_id=new.lineitem_id limit 1;
SELECT projectid into @projectid from ld_customform24 where customform24id=@customform24id limit 1;

SELECT 1 into @panduancailiao from ld_purchaseinquiryorder where projectid=@projectid and deleted=0 limit 1;



if ifnull(@panduancailiao,0)=0 then 
select max(crmid) into  @maxid from ld_crmentity;
INSERT INTO ld_crmentity(crmid,setype) values(@maxid+1, 'PurchaseInquiryOrder');
UPDATE ld_crmentity_seq SET id=(SELECT MAX(crmid) FROM ld_crmentity);

insert into ld_purchaseinquiryorder(
purchaseinquiryorderid,
purchaseinquiryorder_no,
projectid,
smownerid,
smcreatorid,
createdtime,
modifiedtime,
deleted)
values(
@maxid+1,
concat('cailiao',@maxid+1),
@projectid,
1,
1,
now(),
now(),
0);
insert into ld_purchaseinquiryordercf(purchaseinquiryorderid)
values(@maxid+1);

END if;

set @purchaseinquiryorderid=null;
set @maxlineitem_id=null;


SELECT purchaseinquiryorderid into @purchaseinquiryorderid from ld_purchaseinquiryorder 
where projectid=@projectid and deleted=0 limit 1;
select max(lineitem_id) into @maxlineitem_id  from ld_purchaseinquiryorderdetail;


insert into ld_purchaseinquiryorderdetail(id, productid,lineitem_id)
SELECT @purchaseinquiryorderid, productid, (@maxlineitem_id:=@maxlineitem_id+1) from ld_customform24detail a
LEFT JOIN ld_customform12detail b on a.entitytypeid=b.id 
where a.id in (SELECT customform24id from ld_customform24 where projectid=@projectid and deleted=0)  
			and b.productid not in (SELECT ifnull(productid,0) from ld_purchaseinquiryorderdetail where id=@purchaseinquiryorderid)
GROUP BY productid;

insert into ld_purchaseinquiryorderdetailscf(lineitem_id) 
SELECT lineitem_id from ld_purchaseinquiryorderdetail 
where lineitem_id not in (SELECT lineitem_id from ld_purchaseinquiryorderdetailscf);


update ld_purchaseinquiryorderdetail a 
LEFT JOIN (SELECT b1.productid, sum(ifnull(sf140*quantity/cf_2709,0)) as quantity, b1.taxprice,b1.comment  from ld_customform24detail a1 
					LEFT JOIN ld_customform12detail b1 on a1.entitytypeid=b1.id  
					LEFT JOIN ld_customform24detailscf c1 on a1.lineitem_id=c1.lineitem_id
					LEFT JOIN ld_productcf d1 on d1.productid=b1.productid
					where a1.id in (SELECT customform24id from ld_customform24 where projectid=@projectid and deleted=0) 
					GROUP BY b1.productid) b on a.productid=b.productid
set a.quantity=b.quantity, a.taxprice=b.taxprice, a.tax_amount=b.quantity*b.taxprice, a.comment=b.comment
where id=@purchaseinquiryorderid;


update ld_purchaseinquiryorderdetail a
LEFT JOIN ld_purchaseorderdetail b on  a.lineitem_id = b.parent_lineitem_id
set b.`comment`=a.`comment` where a.id=@purchaseinquiryorderid;






delete from ld_purchaseinquiryorderdetail where ifnull(quantity,0)=0;

UPDATE ld_projectcf set cf_2656=(SELECT sum(tax_amount) from ld_purchaseinquiryorderdetail where id=@purchaseinquiryorderid)
where projectid=@projectid;



UPDATE ld_projectcf set cf_2657=(SELECT sum(ifnull(sf154,0)) from ld_customform24detail a 					
					LEFT JOIN ld_customform24detailscf b on a.lineitem_id=b.lineitem_id
 where id in (SELECT customform24id from ld_customform24 where projectid=@projectid and deleted=0))
where projectid=@projectid;

end */;;
DELIMITER ;
