DROP TABLE IF EXISTS `ld_expensedetail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_expensedetail` (
  `expensedetailid` int(19) NOT NULL AUTO_INCREMENT,
  `expensetype` varchar(100) DEFAULT NULL,
  `Startdate` date DEFAULT NULL,
  `enddate` date DEFAULT NULL,
  `Money` decimal(25,2) DEFAULT NULL,
  `description` text,
  `expenseid` int(19) DEFAULT NULL,
  `expenseuse` varchar(200) DEFAULT NULL,
  `Sequence` int(10) DEFAULT NULL,
  `voucherno` varchar(100) DEFAULT NULL,
  `entitytype` varchar(25) DEFAULT NULL,
  `entitytypeid` int(11) DEFAULT '0',
  `entitytype_value` varchar(100) DEFAULT NULL,
  `source_total` decimal(25,6) DEFAULT NULL,
  `rate` decimal(25,2) DEFAULT NULL,
  PRIMARY KEY (`expensedetailid`),
  KEY `idx_expensedetail_expenseid` (`expenseid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1737 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

