--
-- Table structure for table `ld_field`
--

DROP TABLE IF EXISTS `ld_field`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_field` (
  `tabid` int(19) NOT NULL,
  `fieldid` int(19) NOT NULL AUTO_INCREMENT,
  `columnname` varchar(30) NOT NULL,
  `allowhide` varchar(10) DEFAULT 'yes',
  `tablename` varchar(50) NOT NULL,
  `generatedtype` int(19) NOT NULL DEFAULT '0',
  `uitype` varchar(30) NOT NULL,
  `fieldname` varchar(50) NOT NULL,
  `fieldlabel` varchar(50) NOT NULL,
  `readonly` int(1) NOT NULL,
  `presence` int(19) NOT NULL DEFAULT '1',
  `defaultvalue` text,
  `maximumlength` int(19) DEFAULT NULL,
  `sequence` int(19) DEFAULT NULL,
  `block` int(19) DEFAULT NULL,
  `displaytype` int(19) DEFAULT NULL,
  `typeofdata` varchar(100) DEFAULT NULL,
  `quickcreate` int(10) NOT NULL DEFAULT '1',
  `quickcreatesequence` int(19) DEFAULT NULL,
  `info_type` varchar(20) DEFAULT NULL,
  `masseditable` int(10) NOT NULL DEFAULT '1',
  `helpinfo` text,
  `fieldonly` int(11) DEFAULT '0',
  `issmownerid` int(11) DEFAULT '0',
  `searchfieldtype` int(2) DEFAULT NULL,
  `associatedfields` int(1) DEFAULT NULL,
  `associatedsequence` int(11) DEFAULT '0',
  `callchecked` int(11) DEFAULT '0',
  `duplicatefield` int(10) DEFAULT NULL,
  `relate_search_parent_columnname` varchar(50) DEFAULT NULL,
  `approve_demand` int(4) DEFAULT '2',
  `is_checkimportfield` int(1) DEFAULT '0',
  `allowedit` varchar(25) DEFAULT 'yes',
  `allowedit_presence` varchar(25) DEFAULT 'yes',
  `allowcreate` varchar(25) DEFAULT 'yes',
  `allowcreate_presence` varchar(25) DEFAULT 'yes',
  `allowdetail_presence` varchar(25) DEFAULT 'yes',
  `fldallow_rewriting` int(11) DEFAULT '0',
  `take_photo_only` int(11) DEFAULT '0',
  `savedatabase` varchar(50) DEFAULT 'yes',
  `bigtype` varchar(50) DEFAULT NULL,
  `datarang` varchar(50) DEFAULT NULL,
  `maxrowsshow` int(11) DEFAULT '0',
  `parentbigtype` varchar(50) DEFAULT NULL,
  `profileeditfield` varchar(50) DEFAULT 'yes',
  `keywords` varchar(20) DEFAULT NULL,
  `advance_demand` text,
  `advance_demand_groups` text,
  PRIMARY KEY (`fieldid`),
  KEY `field_tabid_idx` (`tabid`) USING BTREE,
  KEY `field_fieldname_idx` (`fieldname`) USING BTREE,
  KEY `field_block_idx` (`block`) USING BTREE,
  KEY `field_displaytype_idx` (`displaytype`) USING BTREE,
  KEY `multi_field` (`tablename`,`fieldlabel`,`presence`) USING BTREE,
  KEY `sequence_idx` (`sequence`) USING BTREE,
  CONSTRAINT `ld_field_ibfk_1` FOREIGN KEY (`tabid`) REFERENCES `ld_tab` (`tabid`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3764 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ld_field`
--

LOCK TABLES `ld_field` WRITE;
/*!40000 ALTER TABLE `ld_field` DISABLE KEYS */;
