/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_by_paymentplan1` BEFORE UPDATE ON `ld_paymentplan` FOR EACH ROW 
BEGIN

IF @disable_triggers IS NULL THEN
 

	set new.receivable_balance=round(ifnull(new.amount,0)-ifnull(new.actualamount,0),2);
	

END IF;

END */;;
