/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_invoice_cashtotal_edit` AFTER UPDATE ON `ld_paymentplan` FOR EACH ROW 
BEGIN

IF @disable_triggers IS NULL THEN
 
	
	IF NEW.entitytype='Invoice' AND NEW.entitytypeid>0 THEN
		CALL update_invoice_receivedamount_byinvoiceid(NEW.entitytypeid);
	END IF;

END IF;

END */;;
DELIMITER ;
