/*!50003 CREATE*/ /*!50017 */ /*!50003 TRIGGER `update_invoice_cashtotal_delete` AFTER DELETE ON `ld_paymentplan` FOR EACH ROW BEGIN 
	
	IF OLD.entitytype='Invoice' AND OLD.entitytypeid>0 THEN
		CALL update_invoice_receivedamount_byinvoiceid(OLD.entitytypeid);
	END IF;
END */;;
