--
-- Table structure for table `ld_purchaseorderdetail`
--

DROP TABLE IF EXISTS `ld_purchaseorderdetail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `ld_purchaseorderdetail` (
  `id` int(19) DEFAULT NULL,
  `productid` int(19) DEFAULT NULL,
  `sequence_no` int(4) DEFAULT NULL,
  `quantity` decimal(25,8) DEFAULT NULL,
  `listprice` decimal(25,8) DEFAULT NULL,
  `taxprice` decimal(25,8) DEFAULT NULL,
  `discount_percent` decimal(7,3) DEFAULT NULL,
  `discount_amount` decimal(25,6) DEFAULT NULL,
  `comment` text,
  `description` text,
  `incrementondel` int(11) NOT NULL DEFAULT '0',
  `lineitem_id` int(11) NOT NULL AUTO_INCREMENT,
  `tax1` decimal(7,3) DEFAULT NULL,
  `tax2` decimal(7,3) DEFAULT NULL,
  `tax3` decimal(7,3) DEFAULT NULL,
  `remark` text,
  `firmoffer` decimal(25,8) DEFAULT NULL,
  `profitloss` decimal(25,8) DEFAULT NULL,
  `paperquantity` decimal(25,8) DEFAULT NULL,
  `entitytype` varchar(25) DEFAULT NULL,
  `parent_lineitem_id` int(11) DEFAULT '0',
  `entitytypeid` int(11) DEFAULT '0',
  `havepurchasecount` decimal(25,8) DEFAULT NULL,
  `balancepurchasecount` decimal(25,8) DEFAULT NULL,
  `haveoutproductcount` decimal(25,8) DEFAULT NULL,
  `balanceoutproductcount` decimal(25,8) DEFAULT NULL,
  `productcost` decimal(25,8) DEFAULT NULL,
  `grossprofit` decimal(7,3) DEFAULT NULL,
  `servicecontracts_start_date` date DEFAULT NULL,
  `servicecontracts_end_date` date DEFAULT NULL,
  `rmbprice` decimal(25,6) DEFAULT NULL,
  `tax_customs` decimal(7,3) DEFAULT NULL,
  `tax_added` decimal(7,3) DEFAULT NULL,
  `tax_freight` decimal(7,3) DEFAULT NULL,
  `tax_rate` decimal(10,6) DEFAULT NULL,
  `isintegralset` int(11) DEFAULT '0',
  `discount_total` decimal(25,6) DEFAULT '0.000000',
  `tax_total` decimal(25,6) DEFAULT '0.000000',
  `list_amount` decimal(25,6) DEFAULT '0.000000',
  `tax_amount` decimal(25,6) DEFAULT '0.000000',
  `eur_price` decimal(25,6) DEFAULT '0.000000',
  `tax_profit` decimal(25,6) DEFAULT '0.000000',
  `rmb_taxprice` decimal(25,6) DEFAULT '0.000000',
  `rmb_taxamount` decimal(25,6) DEFAULT '0.000000',
  `contractid` int(19) DEFAULT '0',
  `haveinvoicecount` decimal(25,8) DEFAULT NULL,
  `balanceinvoicecount` decimal(25,8) DEFAULT NULL,
  `lastlistprice` decimal(25,8) DEFAULT NULL,
  `lasttaxprice` decimal(25,8) DEFAULT NULL,
  `serialnumber` varchar(200) DEFAULT NULL,
  `actualtaxprice` decimal(25,8) DEFAULT NULL,
  `batchtext` varchar(200) DEFAULT NULL,
  `wareid` int(11) DEFAULT '0',
  `productbomid` int(19) DEFAULT '0',
  `productbomquantity` int(19) DEFAULT '0',
  PRIMARY KEY (`lineitem_id`),
  KEY `inventoryproductrel_id_idx` (`id`) USING BTREE,
  KEY `inventoryproductrel_productid_idx` (`productid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2257 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

