INSERT INTO `ld_salesordercf` VALUES (1129,'城墙外墙涂料施工工程','城墙外墙涂料施工工程','城墙外墙涂料工程施工合同','网上转账',230000.00),(18543,'环保项目工程施工（31#）','环保项目外墙保温工程施工','环保项目外墙保温工程施工合同','网上转账',1500000.00),(20219,'廊坊项目','机柜、PDU、变压器设备采购','机柜、PDU、变压器','电汇',1000000.00),(20234,'外电工程','全包','外电工程','预付款50%，尾款50%',545000.00),(20238,'分包外电工程','','','预付50%，尾款50%',0.00),(20244,'外墙粉刷','全包','外墙乳胶漆1（新）','企业转账',190000.00),(20282,'工程项目','全包','建筑','企业转账',100000.00),(20405,'校园外墙','全包','弹性外墙漆2\n','企业转站',84096.00),(20819,'楼板底、样板房','地板、油漆','静电地板、油漆等','1.双方协议签署后7日内，甲方支付合同总价50%作为备料款；\n2.乙方物料全部采购完成，邀请甲方到仓储部查验物品（包括查看数量以及品质）并确认符合合同约定要求，甲方在乙方发货前7日支付合同总价的35%作为进场款。\n3.全部物料进场摆放安装完成并经甲方书面验收合格，且双方办理结算完毕后15个工作日内，甲方支付至结算总价的95%。\n4.剩余结算价5%作为质量保证金，如乙方完全履行保修义务且无任何遗留质量问题的，在质量保证期满后20日内无息支付。质量保证期一年, 自项目验收合格并交付甲方使用之日起开始计算。',1207040.00),(20907,'外墙粉刷','全包','外墙乳胶漆1（新）','企业转账',190000.00),(20929,'','','','',1200000.00),(20976,'外墙粉刷','全包','外墙乳胶漆1（新）','现金',3400000.00),(21027,'环保项目工程施工（31#）','环保项目内墙保温工程施工','环保项目内墙保温工程施工合同','现金',5600000.00),(21029,'华润项目工程施工（32#）','华润项目粉刷工程施工','华润项目粉刷工程施工合同','现金',1200000.00),(21157,'工业园建设','墙体、房体','固也泰工业园一期','企业转账',5600000.00),(21162,'教学楼翻新','墙体、地面、课桌椅纸皮更换','教学楼施工一期','支票',928000.00),(21163,'工业园厂房设计维修','厂房房体、绿化','厂房一期','现金',1200000.00);
