LEFT JOIN ld_customform22detail b2 on a2.lineitem_id=b2.lineitem_id GROUP BY id, sf134) d
on d.id=b.id and d.sf134=a.sf134
set a.sf156 = a.sf148*a.sf136/100,
a.sf151 = sf138*sf148*sf136/100/c.zongliang,
a.sf150 = d.longdongheji */ ;;
