/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		insert into ld_crmentity(crmid,setype)
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0
		from dual where not exists (select 1 from ld_reminds where content=tmp_content AND recieverid=tmp_recieverid and related_to=tmp_related_to and date_time=tmp_remindtime and reminds_ruleid=tmp_ruleid);

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_shujuzidian` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_shujuzidian`(
	tmp_modulelabel VARCHAR(100)
)
BEGIN

	SET @my_tabid=(
		SELECT
			GROUP_CONCAT(a.tabid) AS tabids
		FROM ld_tab a
		INNER JOIN ld_tranlabel b ON b.Relateid=a.tabid AND b.trantable='ld_tab'
		WHERE a.`name`=tmp_modulelabel
			OR b.fieldlabel=tmp_modulelabel
		GROUP BY a.tabid
	);

	SELECT
		bill_name AS '表单名称',
		block_name AS '区块名称',
		field_name AS '字段名称',
		filed_type AS '字段类型',
		table_name AS '数据库表名',
		show_name AS '显示名称（CH）'
	FROM (
		(SELECT
			1 AS type_seq,
			c.sequence AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS bill_name,
			CONCAT('单据表头-',e.fieldlabel) AS block_name,
			b.columnname AS field_name,
			s.COLUMN_TYPE AS filed_type,
			b.tablename AS table_name,
			d.fieldlabel AS show_name
		FROM ld_tab a
		LEFT JOIN ld_field b ON a.tabid=b.tabid
		LEFT JOIN ld_blocks c ON c.blockid=b.block
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_field' AND d.Relateid=b.fieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel e ON e.trantable='ld_blocks' AND e.Relateid=c.blockid AND e.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			2 AS type_seq,
			1000000 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_producttoolfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_producttoolfield' AND d.Relateid=b.producttoolfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
		UNION ALL
		(SELECT
			3 AS type_seq,
			1000001 AS block_seq,
			b.sequence AS field_seq,
			f.fieldlabel AS '表单名称',
			'单据分录-字段信息' AS '区块名称',
			b.columnname AS '字段名称',
			s.COLUMN_TYPE AS '字段类型',
			b.tablename AS '数据库表名',
			d.fieldlabel AS '显示名称（CH）'
		FROM ld_tab a
		LEFT JOIN ld_tabdetailfield b ON a.tabid=b.tabid
		LEFT JOIN ld_tranlabel d ON d.trantable='ld_tabdetailfield' AND d.Relateid=b.tabdetailfieldid AND d.languagetype='zh'
		LEFT JOIN ld_tranlabel f ON f.trantable='ld_tab' AND f.Relateid=a.tabid AND f.languagetype='zh'
		INNER JOIN information_schema.COLUMNS s ON s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=b.tablename AND s.COLUMN_NAME=b.columnname
		WHERE FIND_IN_SET(a.tabid,@my_tabid)
			AND b.presence<>1)
	) tmp_zidan
	ORDER BY type_seq,block_seq,field_seq;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_attachments_notes` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_attachments_notes`(
)
BEGIN

	DECLARE tmp_crmid INT(19) DEFAULT 0;
	DECLARE tmp_attid INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
				SELECT
					b.crmid,
					b.attachmentsid
				FROM ld_notes a
				INNER JOIN ld_seattachmentsrel b ON a.notesid=b.crmid
				ORDER BY b.crmid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_crmid = NULL;
	
	OPEN mycursor;
	FETCH mycursor INTO tmp_crmid,tmp_attid;
	WHILE(tmp_crmid IS NOT NULL) DO
		SET @sql1=CONCAT("UPDATE ld_attachments SET `name`=REPLACE(`name`,'",tmp_crmid,"_','",tmp_attid,"_') WHERE attachmentsid=",tmp_attid);
		PREPARE stalter FROM @sql1;
		EXECUTE stalter;
		FETCH mycursor INTO tmp_crmid,tmp_attid;
	END WHILE;
	CLOSE mycursor;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_all` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_all`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
			SELECT DISTINCT smownerid FROM ld_addjobbill
			UNION 
			SELECT DISTINCT smownerid FROM ld_minusjobbill ORDER BY smownerid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_id = NULL;

	OPEN mycursor;
	Fetch mycursor INTO tmp_id;
	WHILE(tmp_id IS NOT NULL) DO
		CALL ldcrm_update_sykq_byuserid(tmp_id);
		Fetch mycursor INTO tmp_id;
	END WHILE;
	CLOSE mycursor;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_bycrmid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_bycrmid`(
	tmp_id int(19)
)
BEGIN

	IF EXISTS (SELECT 1 FROM ld_crmentity WHERE crmid=tmp_id AND setype='MinusJobBill') THEN
		UPDATE ld_minusjobbill a
		LEFT JOIN ld_minusjobbillscf b ON a.minusjobbillid=b.minusjobbillid
		LEFT JOIN (
			SELECT
				a.id, 
				a.last_name,
				IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
					-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
						0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
						0
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
						5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
						10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
						15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					ELSE 112
				END AS total_sy_nj
			FROM (
				SELECT
						a.id,
						a.last_name,
						a.`status`,
						a.hire_date,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
							ELSE
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
						END AS this_njstart,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							ELSE
								DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
						END AS extra_njend
					FROM ld_users a
			) a
		) t ON a.smownerid=t.id
		SET b.sytx=t.total_sy_tx,b.synj=t.total_sy_nj
		WHERE b.minusjobbillid=tmp_id;
	ELSE 
		UPDATE ld_addjobbill a
		LEFT JOIN ld_addjobbillscf b ON a.addjobbillid=b.addjobbillid
		LEFT JOIN (
			SELECT
				a.id, 
				a.last_name,
				IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
					-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
						0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
						0
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
						5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
						10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
						15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					ELSE 112
				END AS total_sy_nj
			FROM (
				SELECT
						a.id,
						a.last_name,
						a.`status`,
						a.hire_date,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
							ELSE
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
						END AS this_njstart,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							ELSE
								DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
						END AS extra_njend
					FROM ld_users a
			) a
		) t ON a.smownerid=t.id
		SET b.sytx=t.total_sy_tx,b.synj=t.total_sy_nj
		WHERE b.minusjobbillid=tmp_id;
	END IF;
	
end ;;
DELIMITER ;
