DELIMITER ;;
CREATE  PROCEDURE `ldcrm_update_sykq_byuserid`(
	tmp_id int(19)
)
BEGIN
  
    insert into ld_minusjobbillscf(minusjobbillid)
    select minusjobbillid from ld_minusjobbill where minusjobbillid not in (select minusjobbillid from ld_minusjobbillscf);
    
	
	UPDATE ld_minusjobbill a
	LEFT JOIN ld_minusjobbillscf b ON a.minusjobbillid=b.minusjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;


    insert into ld_addjobbillscf(addjobbillid)
    select addjobbillid from ld_addjobbill where addjobbillid not in (select addjobbillid from ld_addjobbillscf);

	
	UPDATE ld_addjobbill a
	LEFT JOIN ld_addjobbillscf b ON a.addjobbillid=b.addjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;
	
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `lingdang_reset_demodb_everyday` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `lingdang_reset_demodb_everyday`(
)
BEGIN

	
	SET @record_step=2;
	
	
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_account WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(accountid) FROM (SELECT accountid FROM ld_account WHERE deleted=0 ORDER BY accountid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_account SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(accountid,@mycrmid) ORDER BY accountid DESC;
		SET @j=@j+1;
	END WHILE;

	
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactdetails WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactid) FROM (SELECT contactid FROM ld_contactdetails WHERE deleted=0 ORDER BY contactid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactdetails SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactid,@mycrmid) ORDER BY contactid DESC;
		SET @j=@j+1;
	END WHILE;

	
	SET @record_step=5;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_contactrecords WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(contactrecordID) FROM (SELECT contactrecordID FROM ld_contactrecords WHERE deleted=0 ORDER BY contactrecordID DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_contactrecords SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(contactrecordID,@mycrmid) ORDER BY contactrecordID DESC;
		SET @j=@j+1;
	END WHILE;
	UPDATE ld_contactrecords SET contactdate=DATE_ADD(createdtime,INTERVAL 5 HOUR);
	UPDATE ld_contactrecords SET nextContactDate=DATE_ADD(contactdate,INTERVAL 3 DAY);

	
	SET @record_step=3;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_salesorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(salesorderid) FROM (SELECT salesorderid FROM ld_salesorder WHERE deleted=0 ORDER BY salesorderid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_salesorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(salesorderid,@mycrmid) ORDER BY salesorderid DESC;
		SET @j=@j+1;
	END WHILE;
	UPDATE ld_salesorder SET signed_data=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	SET @record_step=2;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_servicecontracts WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(servicecontractsid) FROM (SELECT servicecontractsid FROM ld_servicecontracts WHERE deleted=0 ORDER BY servicecontractsid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_servicecontracts SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(servicecontractsid,@mycrmid) ORDER BY servicecontractsid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_servicecontracts SET due_date=DATE_FORMAT(createdtime,'%Y_%m-%d');

	UPDATE ld_servicecontracts a
	LEFT JOIN ld_servicecontractsdetail b On b.id=a.servicecontractsid
	SET b.servicecontracts_start_date=a.due_date,b.servicecontracts_end_date=DATE_SUB(DATE_ADD(a.due_date,INTERVAL 1 YEAR),INTERVAL 1 DAY);

	DELETE FROM ld_maxservicedate;
	INSERT INTO ld_maxservicedate(inventoryid,productid,accountid,service_enddate)
	SELECT
		id,
		productid,
		accountid,
		MAX(servicecontracts_end_date) AS servicecontracts_end_date
	FROM (
		SELECT
			b.id,
			b.productid,
			a.accountid,
			b.servicecontracts_end_date
		FROM ld_servicecontracts a
		LEFT JOIN ld_servicecontractsdetail b ON b.id=a.servicecontractsid
		WHERE a.deleted=0
			AND a.approvestatus<>'已拒绝'
		ORDER BY a.accountid,b.productid,b.servicecontracts_end_date DESC
	) tmp
	GROUP BY accountid,productid
	ORDER BY accountid,productid;


	
	SET @record_step=1;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_potential WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(potentialid) FROM (SELECT potentialid FROM ld_potential WHERE deleted=0 ORDER BY potentialid DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_potential SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(potentialid,@mycrmid) ORDER BY potentialid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_potential SET closingdate=DATE_ADD(DATE_FORMAT(createdtime,'%Y_%m-%d'),INTERVAL 20 DAY);


	
	SET @record_step=2;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_invoice WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT invoiceid AS id FROM ld_invoice WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_invoice SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime WHERE FIND_IN_SET(invoiceid,@mycrmid) ORDER BY invoiceid DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_invoice SET invoicedate=DATE_FORMAT(createdtime,'%Y_%m-%d');


	
	SET @record_step=3;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_cashbill WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT cashbillid AS id FROM ld_cashbill WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_cashbill SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,cashbilldate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(cashbillid,@mycrmid) ORDER BY cashbillid DESC;
		SET @j=@j+1;
	END WHILE;


	
	SET @record_step=4;
	SET @i=0;
	SET @j=0;
	WHILE @j<(SELECT COUNT(1) FROM ld_outboundorder WHERE deleted=0) DO 
		SET @myquery=CONCAT("SET @mycrmid=(SELECT GROUP_CONCAT(id) FROM (SELECT out_id AS id FROM ld_outboundorder WHERE deleted=0 ORDER BY id DESC LIMIT ",@j*@record_step,',',@record_step,") t )");
		
		PREPARE myexec FROM @myquery;
		EXECUTE myexec;
		DEALLOCATE PREPARE myexec;
		
		UPDATE ld_outboundorder SET createdtime=DATE_SUB(DATE_ADD(DATE_SUB(CURDATE(),INTERVAL @j DAY),INTERVAL 5 HOUR),INTERVAL ((@i:=@i+1)-1)*5 SECOND),modifiedtime=createdtime,outdate=DATE_FORMAT(createdtime,'%Y_%m-%d') WHERE FIND_IN_SET(out_id,@mycrmid) ORDER BY out_id DESC;
		SET @j=@j+1;
	END WHILE;

	UPDATE ld_salestarget SET targetyear=YEAR(CURDATE());

END ;;
