/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_monthreport_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_monthreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(monthreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	IF @remind<>'不提醒' THEN
		IF @remind>=20 AND @remind<32 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DAY(CURDATE())>=@remind-2 AND DAY(CURDATE())<=@remind,1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=@remind-DAY(CURDATE())+1;
		ELSEIF @remind=40 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DATE_ADD(CURDATE(),INTERVAL 2 DAY)>=LAST_DAY(CURDATE()),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_SUB(LAST_DAY(CURDATE()),INTERVAL 2 DAY);	
			SET @days=DATEDIFF(LAST_DAY(CURDATE()),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE())>=25 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(CURDATE()>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(LAST_DAY(CURDATE()), INTERVAL @remind DAY),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE()) IN (1,2) THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),CURDATE())+1;
		ELSEIF @remind>=3 AND @remind<=5 THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY) AND CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),CURDATE())+1;
		ELSE 
				SET @do_remind=0;
		END IF;

		IF @do_remind=1 AND @cnt=0 THEN 
			OPEN Mycur;
			FETCH Mycur INTO tmp_id;
			WHILE (tmp_id IS NOT NULL) DO
				IF NOT EXISTS (SELECT 1 FROM ld_monthreport WHERE monthofyear=@yue AND `Status`=1 AND smcreatorid=tmp_id) THEN
					IF @days=1 THEN
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，今天就是提交期限哦');
					ELSE
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，还有',@days,'天就是提交期限哦');
					END IF;
					CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
				END IF;
			FETCH Mycur INTO tmp_id;
			END WHILE;
			CLOSE Mycur;	
		END IF;
	END IF;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_servicecharge_remind_lastservicedate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_servicecharge_remind_lastservicedate`(
)
BEGIN
	

	declare tmp_accountid int(19) default 0;
	declare tmp_accountname varchar(255) default NULL;
	declare tmp_date date default NULL;
	declare tmp_recieverid int(19) default 0;
	declare tmp_days int(19) default 0;

	declare cur1 cursor for SELECT 
								accountid,
								accountname,
								lastservicedate,
								CASE WHEN servicecasher>0 THEN servicecasher ELSE 1 END AS servicecasher,
								DATEDIFF(lastservicedate,CURDATE()) AS days
							FROM ld_account
							WHERE deleted=0
								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;

	OPEN cur1;
	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	while(tmp_accountid is not null) DO
		IF tmp_days<=-30 THEN
			SET @remind_type='自动任务之服务过期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务过期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经过期',abs(tmp_days),'天（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';			
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN
			SET @remind_type='自动任务之服务到期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务到期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经到期（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';			
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN
			SET @remind_type='自动任务之服务即将到期提醒';
			
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务即将到期提醒%') THEN
				
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'还有',abs(tmp_days),'天（',tmp_date,'）即将到期，请及时跟进！');
				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				insert into ld_crmentity(crmid,setype)
				select @maxid+1,'Reminds';			
				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		END IF;
		
		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	end while;
	close cur1;


end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `task_weekreport_reminder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `task_weekreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(weekreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '周报提交提醒：%' AND WEEK(date_time)=WEEK(CURDATE());

	IF @remind<>'不提醒' AND WEEKDAY(NOW())IN (@remind-2,@remind-1) AND @cnt=0 THEN
		OPEN Mycur;
		FETCH Mycur INTO tmp_id;
		WHILE (tmp_id IS NOT NULL) DO
			IF NOT EXISTS (SELECT 1 FROM ld_weekreport WHERE Weeksofyear=WEEK(CURDATE()) AND yearbol=YEAR(CURDATE()) AND `status`=1 AND smcreatorid=tmp_id) THEN
				IF WEEKDAY(NOW())=@remind-2 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，明天是最后一天期限哦');
				ELSEIF WEEKDAY(CURDATE())=@remind-1 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，今天是最后一天期限哦');
				END IF;
				CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
			END IF;
		FETCH Mycur INTO tmp_id;
		END WHILE;
		CLOSE Mycur;	
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `taxamountreverseallproducttool` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `taxamountreverseallproducttool`()
BEGIN
	
	declare done  int  default 0;
 declare ttabid  int ;
	declare cur2 CURSOR FOR SELECT tabid    FROM  ld_producttoolfield  where columnname='tax_amount' group by tabid ;
	declare continue handler  for not   found  SET done =1;
select deploy_value into @deploy_value from ld_systems_deploy where deploy_type=140;
	OPEN cur2;
	Fetch cur2 into ttabid;

 	loop1: while  done<>1 DO
		
			call reverseproducttooldiscount(ttabid);
		  call reverseproducttoolprice(ttabid);
		  Fetch cur2 into ttabid;
	end while loop1;
	close cur2;
	 update ld_reverseformula inner join ld_producttoolfield  on ld_producttoolfield.producttoolfieldid=ld_reverseformula.parentid
    set reversefieldtype='listprice'
    where reversetable='ld_producttoolfield' and reversefieldtype is null and ld_producttoolfield.columnname='tax_amount' ;
	
  update ld_reverseformula set activatestatus='no';
  set @sql=concat('update ld_reverseformula set activatestatus="yes" where  reversefieldtype="',@deploy_value,'"');

	PREPARE altersql from @sql;
	execute altersql;
  DEALLOCATE PREPARE altersql;
    
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_account_lastcontactuser` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_account_lastcontactuser`(
)
BEGIN
	
	
		declare tmp_accountid int;
		declare tmp_smownerid int;

		declare cur1 CURSOR FOR select b.accountid,a.smownerid
														from (
																select 
																accountid,smownerid,max(contactdate) as contactdate
																from ld_contactrecords 
																where deleted=0 and accountid>0 
																GROUP BY accountid
																order by accountid, contactdate DESC) a 
														INNER JOIN ld_account b on a.accountid=b.accountid
														where b.lastcontactuser=0 and a.smownerid>0;

		DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
		OPEN cur1;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		while(tmp_accountid is not null) DO
				update ld_account set lastcontactuser=tmp_smownerid where lastcontactuser=0 and accountid=tmp_accountid;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		end while;
		close cur1;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_account_lastservicedate` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_account_lastservicedate`(
)
begin

	declare tmp_accountid int default 0;

	declare cur2 CURSOR FOR select accountid from ld_account;
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
	open cur2;
	fetch cur2 into tmp_accountid;
	while(tmp_accountid is not null) DO
		set @service_enddate=NULL;
		select max(service_enddate) into @service_enddate from ld_maxservicedate where accountid=tmp_accountid;
		
		IF @service_enddate is not NULL THEN
			update ld_account set lastservicedate=@service_enddate where accountid=tmp_accountid;
		ELSE
			set @signed_data=NULL;
			SELECT max(signed_data) into @signed_data FROM ld_salesorder WHERE accountid=tmp_accountid and ifnull(sostatus,'')<>'已作废' and IFNULL(approvestatus,'')<>'已拒绝';
			IF @signed_data is not NULL THEN
				update ld_account set lastservicedate=@signed_data where accountid=tmp_accountid;
			ELSE
				update ld_account set lastservicedate=DATE_FORMAT(createdtime,'%Y-%m-%d') where accountid=tmp_accountid;
			END IF;
		END IF;

		Fetch cur2 into tmp_accountid;
	end while;
	close cur2;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_cashbill2paymentplan_entitytype` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_cashbill2paymentplan_entitytype`(
)
begin

	set @cnt=0;
	select count(1) into @cnt from ld_cashbill2paymentplan where entitytypeid>0 and LENGTH(ifnull(entitytype,''))<1;
	IF @cnt>0 THEN

		update ld_cashbill2paymentplan a
		LEFT JOIN ld_crmentity b on a.entitytypeid=b.crmid
		set a.entitytype=b.setype
		where a.entitytypeid>0 and LENGTH(ifnull(a.entitytype,''))<1;

	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_invoice_receivedamount_byinvoiceid` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_invoice_receivedamount_byinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_invoice WHERE invoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE invoiceid=tmp_invoiceid;
	ELSE
		
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE invoiceid=tmp_invoiceid;
	END IF;

end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
