/*!50003 DROP PROCEDURE IF EXISTS `update_products_ststus1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_products_ststus1`(
)
begin

	declare done  int  default 0;
	declare tmpproductid int default 0;

	
	declare tmpdescription varchar(200) default null;

	
	declare curw CURSOR FOR SELECT productid,description FROM  ld_products;

	declare continue handler  for not   found  SET done =1;

	OPEN curw;
		Fetch curw INTO tmpproductid,tmpdescription;
		loop1: while  done<>1 DO
			
			
			SET @salesorderid=0;
			SELECT
				ld_salesorder.salesorderid INTO @salesorderid
			FROM ld_salesorder
			LEFT JOIN ld_salesorderdetail ON ld_salesorder.salesorderid=ld_salesorderdetail.id
			WHERE ld_salesorder.deleted=0 
				AND ld_salesorder.approvestatus='已批准'
				AND ld_salesorderdetail.productid=tmpproductid 
			ORDER BY ld_salesorder.signed_data DESC LIMIT 1;

			IF @salesorderid>0 THEN
			
				
				
				SET @service_end_date=NULL;
				SELECT
					IFNULL(ld_servicecontractsdetail.servicecontracts_end_date,'1900-01-01') INTO @service_end_date
				FROM ld_servicecontracts
				LEFT JOIN ld_servicecontractsdetail ON ld_servicecontracts.servicecontractsid=ld_servicecontractsdetail.id
				WHERE ld_servicecontracts.deleted=0 
					AND ld_servicecontractsdetail.productid=tmpproductid 
				ORDER BY ld_servicecontractsdetail.servicecontracts_end_date DESC LIMIT 1;
				
				IF @service_end_date='1900-01-01' THEN
					
					UPDATE ld_products SET description='已售' WHERE productid=tmpproductid;
				
				ELSEIF @service_end_date>=CURDATE() THEN
					
					UPDATE ld_products SET description='已租' WHERE productid=tmpproductid;
					
				ELSE
					
					UPDATE ld_products SET description='待售租' WHERE productid=tmpproductid;
				END IF;
			
			ELSE
				
				UPDATE ld_products SET description='待售租' WHERE productid=tmpproductid;
			END IF;

		Fetch curw INTO tmpproductid,tmpdescription;
		end while loop1;
	close curw;
end ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `update_purchase` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE  PROCEDURE `update_purchase`()
begin

update ld_purchaseorder a 
inner JOIN ld_purchaseorderdetail b on a.purchaseorderid=b.id
inner JOIN ld_purchaseinquiryorder c on a.projectid=c.projectid
inner JOIN ld_purchaseinquiryorderdetail d on c.purchaseinquiryorderid=d.id and b.productid=d.productid
set b.entitytype='PurchaseInquiryOrder',
b.entitytypeid = c.purchaseinquiryorderid,
b.parent_lineitem_id = d.lineitem_id,
b.`comment` = d.`comment`;


update ld_purchaseinquiryorderdetail a
LEFT JOIN ld_purchaseinquiryorderdetailscf b on a.lineitem_id= b.lineitem_id
LEFT JOIN (SELECT sum(quantity) as quantity, parent_lineitem_id from ld_purchaseorderdetail a1 
			LEFT JOIN ld_purchaseorder b1 on a1.id=b1.purchaseorderid where b1.deleted=0 and b1.approvestatus='已批准'  GROUP BY parent_lineitem_id) c 
			on a.lineitem_id=c.parent_lineitem_id
set b.sf2923=ifnull(c.quantity,0), b.sf3059=a.quantity-ifnull(c.quantity,0);


update ld_purchaseorderdetailscf a 
LEFT JOIN ld_purchaseorderdetail b on a.lineitem_id=b.lineitem_id
LEFT JOIN ld_purchaseinquiryorderdetail c on b.parent_lineitem_id=c.lineitem_id
LEFT JOIN ld_purchaseinquiryorderdetailscf d on c.lineitem_id=d.lineitem_id
set a.sf2923=d.sf2923,
		a.sf3059=d.sf3059,
		a.sf3195=c.quantity;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
